import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    A = int(input_data[0])
    B = int(input_data[1])

    # S_A ocupa os próximos A elementos
    # S_B ocupa os próximos B elementos
    idx = 2
    S_A = input_data[idx:idx + A]
    idx += A
    S_B = input_data[idx:idx + B]

    ptr_B = 0
    for x in S_A:
        if x == S_B[ptr_B]:
            ptr_B += 1
            if ptr_B == B:
                break

    if ptr_B == B:
        print('S')
    else:
        print('N')

if __name__ == '__main__':
    main()
